CREATE PROCEDURE [sync].[gsp_ServerSelectUpdateConflicts_tblTransactions]
@TransactionGuid uniqueidentifier
AS
BEGIN
    -- This command is used if @sync_row_count returns
    -- 0 when changes are applied to the server.
    --
    SELECT [dbo].[tblTransactions].[TransID],[dbo].[tblTransactions].[AliasName],[dbo].[tblTransactions].[SubType],[dbo].[tblTransactions].[Site],[dbo].[tblTransactions].[TransReferenceID],CONVERT(CHAR(10), [dbo].[tblTransactions].[InventoryDate], 111) AS [InventoryDate],[dbo].[tblTransactions].[ShipToID],[dbo].[tblTransactions].[ShipToCode],[dbo].[tblTransactions].[SupplierID],[dbo].[tblTransactions].[SupplierCode],[dbo].[tblTransactions].[CreatedDate],[dbo].[tblTransactions].[CreatedBy],[dbo].[tblTransactions].[RequestedDeliveryDate],[dbo].[tblTransactions].[UpdatedDate],[dbo].[tblTransactions].[UpdatedBy],[dbo].[tblTransactions].[TransDateTime],[dbo].[tblTransactions].[TransVersion],[dbo].[tblTransactions].[SCACCode],[dbo].[tblTransactions].[CardNumber],[dbo].[tblTransactions].[ShipmentNumber],[dbo].[tblTransactions].[ShipperID],[dbo].[tblTransactions].[ShipperCode],[dbo].[tblTransactions].[OwnerID],[dbo].[tblTransactions].[OwnerCode],[dbo].[tblTransactions].[ManagerID],[dbo].[tblTransactions].[ManagerCode],[dbo].[tblTransactions].[CarrierID],[dbo].[tblTransactions].[CarrierCode],[dbo].[tblTransactions].[ConjoinTransID],[dbo].[tblTransactions].[ReversedTransID],[dbo].[tblTransactions].[LinkedDocumentNumber],[dbo].[tblTransactions].[ReversalType],[dbo].[tblTransactions].[PONumber],[dbo].[tblTransactions].[TimeIn],[dbo].[tblTransactions].[TimeOut],[dbo].[tblTransactions].[TimeEnd],[dbo].[tblTransactions].[RoutingID],[dbo].[tblTransactions].[TicketSource],[dbo].[tblTransactions].[LoadID],[dbo].[tblTransactions].[BillToID],[dbo].[tblTransactions].[BillToCode],[dbo].[tblTransactions].[DriverIdentificationNumber],[dbo].[tblTransactions].[CreditAmount],[dbo].[tblTransactions].[CardExpiration],[dbo].[tblTransactions].[CardName],[dbo].[tblTransactions].[CardType],[dbo].[tblTransactions].[CashAmount],[dbo].[tblTransactions].[RouteOriginationDate],[dbo].[tblTransactions].[InternationalRouteIndicator],[dbo].[tblTransactions].[PreviousRoutingID],[dbo].[tblTransactions].[ShippingDocumentNumber],[dbo].[tblTransactions].[DocumentNumber],[dbo].[tblTransactions].[STD],[dbo].[tblTransactions].[ETD],[dbo].[tblTransactions].[STA],[dbo].[tblTransactions].[ETA],[dbo].[tblTransactions].[SFT],[dbo].[tblTransactions].[FST],[dbo].[tblTransactions].[EstimatedFuelingDuration],[dbo].[tblTransactions].[DeleteFlag],[dbo].[tblTransactions].[TicketMode],[dbo].[tblTransactions].[DestinationRegistrationID1],[dbo].[tblTransactions].[DestinationSerialNumber1],[dbo].[tblTransactions].[DestinationEquipmentType1],[dbo].[tblTransactions].[DestinationEquipmentModel1],[dbo].[tblTransactions].[DestinationCompanyEquipmentID1],[dbo].[tblTransactions].[DestinationRegistrationID2],[dbo].[tblTransactions].[DestinationSerialNumber2],[dbo].[tblTransactions].[DestinationEquipmentType2],[dbo].[tblTransactions].[DestinationEquipmentModel2],[dbo].[tblTransactions].[DestinationCompanyEquipmentID2],[dbo].[tblTransactions].[DestinationRegistrationID3],[dbo].[tblTransactions].[DestinationSerialNumber3],[dbo].[tblTransactions].[DestinationEquipmentType3],[dbo].[tblTransactions].[DestinationEquipmentModel3],[dbo].[tblTransactions].[DestinationCompanyEquipmentID3],[dbo].[tblTransactions].[SourceRegistrationID1],[dbo].[tblTransactions].[SourceSerialNumber1],[dbo].[tblTransactions].[SourceEquipmentType1],[dbo].[tblTransactions].[SourceEquipmentModel1],[dbo].[tblTransactions].[SourceCompanyEquipmentID1],[dbo].[tblTransactions].[SourceRegistrationID2],[dbo].[tblTransactions].[SourceSerialNumber2],[dbo].[tblTransactions].[SourceEquipmentType2],[dbo].[tblTransactions].[SourceEquipmentModel2],[dbo].[tblTransactions].[SourceCompanyEquipmentID2],[dbo].[tblTransactions].[SourceRegistrationID3],[dbo].[tblTransactions].[SourceSerialNumber3],[dbo].[tblTransactions].[SourceEquipmentType3],[dbo].[tblTransactions].[SourceEquipmentModel3],[dbo].[tblTransactions].[SourceCompanyEquipmentID3],[dbo].[tblTransactions].[OperatorID],[dbo].[tblTransactions].[EffectiveDate],[dbo].[tblTransactions].[ExpirationDate],[dbo].[tblTransactions].[ScheduledDate],[dbo].[tblTransactions].[AutoComplete],[dbo].[tblTransactions].[Flag01],[dbo].[tblTransactions].[Flag02],[dbo].[tblTransactions].[Flag03],[dbo].[tblTransactions].[Flag04],[dbo].[tblTransactions].[Flag05],[dbo].[tblTransactions].[Flag06],[dbo].[tblTransactions].[Number01],[dbo].[tblTransactions].[Number02],[dbo].[tblTransactions].[Number03],[dbo].[tblTransactions].[Number04],[dbo].[tblTransactions].[Number05],[dbo].[tblTransactions].[Number06],[dbo].[tblTransactions].[ContactFirstName],[dbo].[tblTransactions].[ContactSurname],[dbo].[tblTransactions].[Date01],[dbo].[tblTransactions].[Date02],[dbo].[tblTransactions].[Date03],[dbo].[tblTransactions].[Date04],[dbo].[tblTransactions].[LegacyNumber],[dbo].[tblTransactions].[Country],[dbo].[tblTransactions].[ContactInfo],[dbo].[tblTransactions].[AssociatedDocNumber],[dbo].[tblTransactions].[AssociatedCLIN],[dbo].[tblTransactions].[SubmittedToAccounting],[dbo].[tblTransactions].[FuelCardID],[dbo].[tblTransactions].[AssociatedTransportOrderNumber],[dbo].[tblTransactions].[RequestedDateTime],[dbo].[tblTransactions].[DispatchedDateTime],[dbo].[tblTransactions].[ErrorFlag],[dbo].[tblTransactions].[TransactionGuid],[dbo].[tblTransactions].[SiteGuid],[dbo].[tblTransactions].[LookupTransTypeIndex],[dbo].[tblTransactions].[LookupTransactionStatusIndex],[dbo].[tblTransactions].[LookupOriginApplicationIndex],[dbo].[tblTransactions].[TransactionAliasGuid],[dbo].[tblTransactions].[BillToCompanyGuid],[dbo].[tblTransactions].[Destination1EquipmentGuid],[dbo].[tblTransactions].[Destination2EquipmentGuid],[dbo].[tblTransactions].[Destination3EquipmentGuid],[dbo].[tblTransactions].[FinalStationIATAGuid],[dbo].[tblTransactions].[FuelCardGuid],[dbo].[tblTransactions].[ManagerCompanyGuid],[dbo].[tblTransactions].[NextStationIATAGuid],[dbo].[tblTransactions].[OperatorPersonnelGuid],[dbo].[tblTransactions].[OriginStationIATAGuid],[dbo].[tblTransactions].[OwnerCompanyGuid],[dbo].[tblTransactions].[PreviousStationIATAGuid],[dbo].[tblTransactions].[ShipperCompanyGuid],[dbo].[tblTransactions].[ShipToCompanyGuid],[dbo].[tblTransactions].[Source1EquipmentGuid],[dbo].[tblTransactions].[Source2EquipmentGuid],[dbo].[tblTransactions].[Source3EquipmentGuid],[dbo].[tblTransactions].[SupplierCompanyGuid],[dbo].[tblTransactions].[CarrierCompanyGuid],[dbo].[tblTransactions].[ReasonCodeGuid],[dbo].[tblTransactions].[OriginStationIATAID],[dbo].[tblTransactions].[PreviousStationIATAID],[dbo].[tblTransactions].[NextStationIATAID],[dbo].[tblTransactions].[FinalStationIATAID],[dbo].[tblTransactions].[OperatorName],[dbo].[tblTransactions].[FuelAdditiveFlag],[dbo].[tblTransactions].[IssuePoint],[dbo].[tblTransactions].[IssuePointNumber],[dbo].[tblTransactions].[RadioNumber],[dbo].[tblTransactions].[GateID],[dbo].[tblTransactions].[GateGuid],[dbo].[tblTransactions].[ShippingMethod],[dbo].[tblTransactions].[ReferencedTransactionGuid], CT.UpdatedContext, CT.UpdatedRowVersion AS '_RowVersion'
